@Component("inventoryItem-handler")
@ProcessingGroup("inventoryItem-processing-group")
public class InventoryItemEventHandler {
	
	// core constructor
	InventoryItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInventoryItemEvent
     */
    @EventHandler
    public void handle( CreateInventoryItemEvent event) {
        entityManager.persist(new InventoryItem(event.getInventoryItemId(), event.getQuantityOnHand(), event.getQuantityReserved(), event.getLotNumber(), event.getComponent(), event.getWarehouse()));
    }

    /*
     * @param	event UpdateInventoryItemEvent
     */
    @EventHandler
    public InventoryItem handle( UpdateInventoryItemEvent event) {
    	entityManager.merge(new InventoryItem(event.getInventoryItemId(), event.getQuantityOnHand(), event.getQuantityReserved(), event.getLotNumber(), event.getComponent(), event.getWarehouse()));
    }
    
    /*
     * @param	event DeleteInventoryItemEvent
     */
    @EventHandler
    public void on( DeleteInventoryItemEvent event) {
    	InventoryItem entity = new InventoryItem();
   
    	// ------------------------------------------
    	// apply the InventoryItemId
    	// ------------------------------------------
    	entity.setInventoryItemId( event.getInventoryItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InventoryItemRepository inventoryItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InventoryItemEventHandler.class.getName());

}
